<?php namespace App\Http\Controllers; use App\Models\Offer; use Illuminate\Http\Request; class CatalogController extends Controller { public function index(Request $r){$q=trim((string)$r->query('q')); $offers=Offer::with(['medicine','organization'])->where('is_active',true)->when(mb_strlen($q)>=2,function($x)use($q){$x->whereHas('medicine',fn($m)=>$m->where('search_text','ilike','%'.$q.'%'));})->when($r->city,fn($x,$v)=>$x->whereHas('organization',fn($o)=>$o->where('city',$v)))->when($r->supplier,fn($x,$v)=>$x->where('organization_id',$v))->when($r->form,fn($x,$v)=>$x->whereHas('medicine',fn($m)=>$m->where('form',$v)))->when($r->min_price,fn($x,$v)=>$x->where('price','>=',$v))->when($r->max_price,fn($x,$v)=>$x->where('price','<=',$v))->orderBy('price')->paginate(20)->withQueryString(); return view('catalog.index',compact('offers','q'));} }
